<?php defined('BASEPATH') or exit('No direct script access allowed');$ganttEscape=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$gantt_json=json_encode($project_gantt,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_THROW_ON_ERROR);$gantt_base=$url.'?operation_kind=projects&resource_id='.$gantt_project_id.'&project_task='; ?>
<section id="portal-project-gantt"><h2>Gantt do projeto</h2><p>Datas reais revisadas, tarefas e grupos publicados. Consulta sem arrastar ou alterar datas. Os tempos, quando permitidos, somam somente os apontamentos encerrados publicados.</p><?php if(!$project_gantt['groups']){ ?><p>Nenhuma tarefa publicada com data inicial revisada disponível no Gantt.</p><?php }else{ ?><label for="portal-gantt-mode">Escala</label><select id="portal-gantt-mode"><option value="Day">Dia</option><option value="Week">Semana</option><option value="Month" selected>Mês</option><option value="Year">Ano</option></select><div id="portal-gantt-chart" tabindex="0" style="overflow-x:auto" aria-label="Cronograma de consulta"></div>
<div style="overflow-x:auto"><table><caption>Datas do cronograma publicado</caption><thead><tr><th>Marco</th><th>Tarefa</th><th>Início</th><th>Prazo</th><th>Estado</th><th>Tempo publicado</th></tr></thead><tbody><?php foreach($project_gantt['groups'] as $group){foreach($group['tasks'] as $gtask){ ?><tr><td><?= $ganttEscape($group['name']); ?></td><td><a href="<?= $ganttEscape($gantt_base.(int)$gtask['id']); ?>"><?= $ganttEscape($gtask['name']); ?></a></td><td><?= $ganttEscape($gtask['start_date']); ?></td><td><?= $ganttEscape($gtask['due_date']); ?></td><td><?= $ganttEscape(['todo'=>'A fazer','in_progress'=>'Em andamento','done'=>'Concluída'][$gtask['status']]??'Indisponível'); ?></td><td><?php if(isset($gtask['published_logged_seconds'])){$secs=$gtask['published_logged_seconds'];echo intdiv($secs,3600).'h '.intdiv($secs%3600,60).'min '.($secs%60).'s';}else{echo 'Não publicado';} ?></td></tr><?php }} ?></tbody></table></div>
<script type="application/json" id="portal-gantt-data" nonce="<?= $ganttEscape($script_nonce??''); ?>"><?= $gantt_json; ?></script>
<script nonce="<?= $ganttEscape($script_nonce??''); ?>">
(function(){'use strict';const data=JSON.parse(document.getElementById('portal-gantt-data').textContent),host=document.getElementById('portal-gantt-chart'),mode=document.getElementById('portal-gantt-mode'),ns='http://www.w3.org/2000/svg',base=<?= json_encode($gantt_base,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_THROW_ON_ERROR); ?>,day=86400000,start=Date.parse(data.start_date+'T00:00:00Z'),end=Date.parse(data.due_date+'T00:00:00Z')+day,span=Math.max(1,(end-start)/day);function node(name,attrs,text){const el=document.createElementNS(ns,name);for(const[k,v]of Object.entries(attrs||{}))el.setAttribute(k,String(v));if(text!==undefined)el.textContent=text;return el;}function draw(){host.replaceChildren();const width=Math.min(100000,Math.max(700,span*({Day:36,Week:12,Month:4,Year:1}[mode.value]||4))),left=260,plot=width-left,rows=data.groups.reduce((n,g)=>n+1+g.tasks.length,0),svg=node('svg',{width,height:rows*32+60,role:'img','data-mode':mode.value,'aria-label':'Cronograma publicado, escala '+mode.options[mode.selectedIndex].text});svg.append(node('title',{},'Cronograma de consulta; consulte também a tabela de datas.'));for(let tick=0;tick<=8;tick++){const x=left+plot*tick/8,stamp=start+(end-start)*tick/8;svg.append(node('line',{x1:x,y1:26,x2:x,y2:rows*32+50,stroke:'#d1d5db'}));svg.append(node('text',{x,y:18,fill:'#334155','font-size':11},new Date(stamp).toISOString().slice(0,10)));}let y=50;const x=date=>left+plot*(Date.parse(date+'T00:00:00Z')-start)/(end-start);for(const group of data.groups){svg.append(node('text',{x:4,y,fill:'#0f172a','font-size':13,'font-weight':'bold'},group.name));svg.append(node('rect',{x:x(group.start_date),y:y-12,width:Math.max(2,x(group.due_date)+plot/span-x(group.start_date)),height:14,fill:'#64748b',rx:3}));y+=32;for(const task of group.tasks){const link=node('a',{href:base+task.id});link.append(node('text',{x:12,y,fill:'#1d4ed8','font-size':12},task.name));const rect=node('rect',{x:x(task.start_date),y:y-12,width:Math.max(2,x(task.due_date)+plot/span-x(task.start_date)),height:18,fill:task.status==='done'?'#15803d':'#2563eb',rx:3});let title=task.name+' · '+task.start_date+' → '+task.due_date;if(Number.isInteger(task.published_logged_seconds))title+=' · '+task.published_logged_seconds+' segundos publicados';rect.append(node('title',{},title));link.append(rect);svg.append(link);y+=32;}}host.append(svg);}mode.addEventListener('change',draw);draw();})();
</script><?php } ?></section>
